//  IDE COMPONENT 
const IDE = ({ project, onBack }) => {
    const [activeTab, setActiveTab] = useState('agent');
    const [activeFile, setActiveFile] = useState('main.fth');
    const [files, setFiles] = useState([]);
    const [fileContent, setFileContent] = useState('');
    const [terminalOutput, setTerminalOutput] = useState([]);
    const [isSidebarOpen, setSidebarOpen] = useState(false);
    const [isToolsOpen, setToolsOpen] = useState(false);
    const [isLoading, setLoading] = useState(false);
    const [agentMessages, setAgentMessages] = useState([]);
    const [showPreview, setShowPreview] = useState(false);

    useEffect(() => {
        fetchFiles();
        checkHealth();
    }, []);

    const checkHealth = async () => {
        try { await fetch(${API_BASE}/health); } catch (e) { console.error(e); }
    };

    const fetchFiles = async () => {
        try {
            const res = await fetch(${API_BASE}/api/file/list);
            if (res.ok) {
                const data = await res.json();
                setFiles(data.files || []);
            } else { throw new Error('Mock'); }
        } catch (e) {
            setFiles([{name: 'main.fth', type: 'file'}, {name: 'frontend.imba', type: 'file'}, {name: 'stilus.css', type: 'file'}]);
        }
        loadFile('main.fth', false);
    };

    const loadFile = async (filename, switchTab = true) => {
        setLoading(true);
        setActiveFile(filename);
        try {
            const res = await fetch(${API_BASE}/api/file?name=${filename});
            if (res.ok) {
                const data = await res.json();
                setFileContent(data.content);
            } else { throw new Error('Mock'); }
        } catch (e) {
            setFileContent(\ ${filename} tartalma...\n\ : hello-world S" Hello ${project?.name || 'World'}!" TYPE CR ;\n\ hello-world);
        } finally {
            setLoading(false);
            if (switchTab) {
                setActiveTab('editor');
                setSidebarOpen(false);
            }
        }
    };

    const handleRun = async () => {
        setTerminalOutput(prev => [...prev, > ${activeFile} futtatása...]);
        setActiveTab('console');
        setTimeout(() => {
             setTerminalOutput(prev => [...prev, Program lefutott sikeresen., Kilépési kód: 0]);
        }, 500);
    };

    const handleAgentChat = async (message) => {
        const newMessage = { role: 'user', content: message };
        setAgentMessages(prev => [...prev, newMessage]);
        setTimeout(() => {
            setAgentMessages(prev => [...prev, { role: 'assistant', content: "Értem. Elkezdtem a kért módosításokat a kódon..." }]);
        }, 1000);
    };

    const ToolItem = ({ icon, title, desc, color, onClick }) => (
        <div onClick={onClick} className="flex gap4 p3 roundedxl active:bgapplesurface transitioncolors cursorpointer bgapplesurface border borderappleborder/50">
            <Icon name={icon} size={24} className={${color} shrink-0 mt-1} />
            <div className="flex flexcol">
                <span className="textappletext fontdisplay fontmedium textbase">{title}</span>
                <span className="textapplesubtext textsm leadingsnug mt1">{desc}</span>
            </div>
        </div>
    );

    return (
        <div className="flex flexcol hscreen wfull bgapplebg relative animatefadein">
            {/ Header /}
            <div className="h14 bgapplebg/90 backdropblurmd flex itemscenter justifybetween px4 borderb borderappleborder z20 safept fixed top0 wfull">
                <button className="textappleblue" onClick={() => setSidebarOpen(true)}>
                    <Icon name="menu" size={24} />
                </button>
                <div className="flex flexcol itemscenter">
                    <span className="textappletext fontdisplay fontsemibold textsm">{project?.name || 'Projekt'}</span>
                    <span className="textapplesubtext text[10px]">Mentve</span>
                </div>
                <button className="textappleblue" onClick={() => setToolsOpen(true)}>
                    <Icon name="morehorizontal" size={24} />
                </button>
            </div>

            {/ Main Content /}
            <main className="flex1 flex flexcol overflowhidden relative">
                {isLoading ? <LoadingSpinner /> : (
                    <>
                        {activeTab === 'editor' && !showPreview && (
                            <div className="flex flex1 overflowhidden bgapplebg relative pt14 pb16">
                                <div className="w10 bgapplebg flex flexcol itemsend pr2 pt4 selectnone borderr borderappleborder z10">
                                    {fileContent.split('\n').map((_, i) => (
                                        <div key={i} className="textxs textapplesubtext fontmono leading6">{i + 1}</div>
                                    ))}
                                </div>
                                <textarea
                                    className="flex1 bgtransparent textappletext fontmono textsm leading6 p4 outlinenone resizenone whitespacepre"
                                    value={fileContent}
                                    onChange={(e) => setFileContent(e.target.value)}
                                    spellCheck="false"
                                />
                            </div>
                        )}
                        {activeTab === 'preview' && (
                            <div className="flex flex1 flexcol itemscenter justifycenter bgapplebg textcenter p8 pt14 pb16">
                                <Icon name="monitor" size={48} className="textapplesubtext mb4" />
                                <h3 className="textappletext fontdisplay fontmedium textlg mb2">Előnézet</h3>
                                <p className="textapplesubtext textsm maxwxs">Az alkalmazás fut, várakozás a kimenetre...</p>
                            </div>
                        )}
                        {activeTab === 'agent' && (
                            <div className="flex flex1 flexcol bgapplebg pt14 pb16">
                                <div className="flex1 overflowyauto p4 spacey4">
                                    {agentMessages.length === 0 ? (
                                        <div className="flex flexcol itemscenter justifycenter hfull mt20">
                                            <div className="w16 h16 bgapplesurface rounded2xl flex itemscenter justifycenter mb4 shadowlg border borderappleborder">
                                                <Icon name="sparkles" className="textappleblue" size={32} />
                                            </div>
                                            <h2 className="textxl fontdisplay fontsemibold textappletext mb2">Szia! Miben segíthetek?</h2>
                                            <p className="textapplesubtext textcenter textsm px8 mb8">Írd le mit szeretnél, és én megírom a kódot.</p>
                                            <div className="grid gridcols2 gap2 wfull px4">
                                                <button className="bgapplesurface textxs textappletext p3 roundedlg border borderappleborder textleft active:bgappleborder transition">Hibakeresés</button>
                                                <button className="bgapplesurface textxs textappletext p3 roundedlg border borderappleborder textleft active:bgappleborder transition">Új funkció</button>
                                            </div>
                                        </div>
                                    ) : (
                                        agentMessages.map((msg, i) => (
                                            <div key={i} className={flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}}>
                                                <div className={max-w-[80%] p-3 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-apple-blue text-white' : 'bg-apple-surface text-apple-text'}}>
                                                    {msg.content}
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                                <div className="p4 bordert borderappleborder bgapplebg safepb">
                                    <div className="bgapplesurface roundedpill flex itemscenter px4 py3 border borderappleborder">
                                        <input
                                            type="text"
                                            placeholder="Ide írj..."
                                            className="bgtransparent flex1 textappletext outlinenone textsm placeholderapplesubtext"
                                            onKeyDown={(e) => {
                                                if (e.key === 'Enter') {
                                                    handleAgentChat(e.target.value);
                                                    e.target.value = '';
                                                }
                                            }}
                                        />
                                        <button className="textappleblue"><Icon name="arrowupcircle" size={24} /></button>
                                    </div>
                                </div>
                            </div>
                        )}
                        {activeTab === 'console' && (
                            <div className="flex flex1 flexcol bgapplebg p4 fontmono textsm overflowyauto pt14 pb16">
                                {terminalOutput.map((line, i) => (
                                    <div key={i} className="textappletext mb1 borderb borderappleborder pb1">{line}</div>
                                ))}
                                <div className="flex itemscenter textapplesubtext mt2">
                                    <span className="mr2">➜</span>
                                    <div className="w2 h4 bgappleblue animatepulse"></div>
                                </div>
                            </div>
                        )}
                    </>
                )}
            </main>

            {/ Bottom Nav /}
            <div className="fixed bottom0 left0 right0 h16 bgapplebg/90 backdropblurmd bordert borderappleborder flex itemscenter px4 justifybetween z30 safepb">
                <button
                    onClick={handleRun}
                    className="w10 h10 bgappleblue roundedfull flex itemscenter justifycenter textwhite shadowlg active:scale95 transitiontransform"
                >
                    <Icon name="play" size={18} fill="currentColor" />
                </button>
                <div className="h10 bgapplesurface roundedfull flex itemscenter p1 border borderappleborder">
                    <button onClick={() => { setActiveTab('preview'); setShowPreview(true); }} className={h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'preview' ? 'bg-apple-border text-white' : 'text-apple-subtext'}}>
                        <Icon name="monitor" size={18} />
                    </button>
                    <button onClick={() => { setActiveTab('agent'); setShowPreview(false); }} className={h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'agent' ? 'bg-apple-border text-apple-blue' : 'text-apple-subtext'}}>
                        <Icon name="sparkles" size={18} />
                    </button>
                    <button onClick={() => { setActiveTab('console'); setShowPreview(false); }} className={h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'console' ? 'bg-apple-border text-white' : 'text-apple-subtext'}}>
                        <Icon name="terminalsquare" size={18} />
                    </button>
                </div>
                <button onClick={() => setToolsOpen(true)} className="w10 h10 flex itemscenter justifycenter textappleblue">
                    <Icon name="layoutgrid" size={22} />
                </button>
            </div>

            {/ Sidebar /}
            <div className={fixed inset-0 z-50 transform transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}}>
                <div className="absolute inset0 bgblack/60 backdropblursm" onClick={() => setSidebarOpen(false)}></div>
                <div className="absolute top0 bottom0 left0 w3/4 maxwxs bgapplesurface borderr borderappleborder flex flexcol animateslideright">
                    <div className="h14 flex itemscenter px4 borderb borderappleborder justifybetween safept bgapplebg/50 backdropblurxl">
                        <span className="fontdisplay fontsemibold textappletext textlg">Fájlok</span>
                        <button onClick={() => setSidebarOpen(false)} className="textappleblue"><Icon name="x" size={20} /></button>
                    </div>
                    <div className="p4">
                        <button onClick={onBack} className="wfull py2 bgapplesurface2 roundedlg textsm textapplered fontmedium flex itemscenter justifycenter gap2 mb4">
                            <Icon name="logout" size={16} /> Kilépés a Főoldalra
                        </button>
                    </div>
                    <div className="flex1 overflowyauto p2">
                        {files.map((file, i) => (
                            <button
                                key={i}
                                onClick={() => loadFile(file.name)}
                                className={w-full flex items-center p-3 rounded-lg mb-1 text-sm transition-colors ${activeFile === file.name ? 'bg-apple-blue text-white' : 'text-apple-subtext hover:text-apple-text hover:bg-white/5'}}
                            >
                                <Icon name={file.name.endsWith('.fth') ? 'filecode' : 'file'} size={18} className="mr3" />
                                <span className="fontmedium">{file.name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/ Tools Modal /}
            <div className={fixed inset-0 z-50 flex items-end justify-center transition-opacity duration-200 ${isToolsOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}}>
                <div className="absolute inset0 bgblack/60 backdropblursm" onClick={() => setToolsOpen(false)}></div>
