                    <div className="flex itemscenter p4 borderb borderappleborder bgapplesurface z10">
                        <button onClick={() => setToolsOpen(false)} className="mlauto textappleblue fontsemibold textsm">Bezárás</button>
                    </div>
                    <div className="flex1 overflowyauto p4 safepb bgapplebg">
                        <div className="spacey4">
                             <ToolItem icon="sparkles" title="Ügynök" desc="Módosítás és javítás." color="textappleblue" onClick={() => { setActiveTab('agent'); setToolsOpen(false); }} />
