                    <div className="flex itemscenter p4 borderb borderappleborder bgapplesurface z10">
                        <button onClick={() => setToolsOpen(false)} className="mlauto textappleblue fontsemibold textsm">Bezárás</button>
                    </div>
                    <div className="flex1 overflowyauto p4 safepb bgapplebg">
                        <div className="spacey4">
                             <ToolItem icon="sparkles" title="Ügynök" desc="Módosítás és javítás." color="textappleblue" onClick={() => { setActiveTab('agent'); setToolsOpen(false); }} />
                             <ToolItem icon="terminal" title="Konzol" desc="Kimenet megtekintése." color="textgray400" onClick={() => { setActiveTab('console'); setToolsOpen(false); }} />
                             <div className="hpx bgappleborder my2"></div>
                             <ToolItem icon="gitbranch" title="Git" desc="Verziókezelés." color="textpurple400" />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

//  MAIN APP WRAPPER 
const App = () => {
    const [view, setView] = useState('dashboard'); // 'dashboard' | 'ide'
    const [activeProject, setActiveProject] = useState(null);

    const handleOpenProject = (project) => {
        setActiveProject(project);
        setView('ide');
    };

    const handleBackToDashboard = () => {
        setActiveProject(null);
        setView('dashboard');
    };

    return (
        <>
            {view === 'dashboard' && <Dashboard onOpenProject={handleOpenProject} />}
            {view === 'ide' && <IDE project={activeProject} onBack={handleBackToDashboard} />}
        </>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
</script>
</body>
</html>
